def comparison(lang):
    def t(zh,en): return zh if lang=='zh' else en
    report='compatibility.html' if lang=='zh' else 'compatibility.en.html'
    clips=[
      ('dual-space','Dual Space · 财联社','Dual Space · CLS','启动后返回列表','Returns to the app list','可见启动页，随后返回 Dual Space 的应用列表。','The launch screen appears, followed by a return to the Dual Space app list.','00:00.8–00:07.8'),
      ('clone-master','分身大师 · 财联社 / 汇丰','Clone Master · CLS / HSBC','同一个双开工具，表现也不同','Different apps, different outcomes','财联社进入首页；随后启动香港汇丰流动理财，等待后返回分身大师列表。两种结果都保留。','CLS reaches its home feed. HSBC HK Mobile Banking then loads and returns to the clone app list. Both outcomes are retained.','00:23.0–00:39.2'),
      ('ourplay','OurPlay · 点点穿书','OurPlay · Diandian Chuanshu','提示“不支持加速”','“Acceleration not supported”','启动过程中显示“当前暂不支持加速”。这是功能限制提示，不作为闪退判定。','The launch sequence displays “Acceleration is currently not supported.” This is a feature limitation, not evidence of a crash.','01:13.5–01:21.1')]
    s=f'''<section class="section comparison-section" id="real-world-comparison"><div class="section-heading"><p class="eyebrow">COMPATIBILITY / REAL FOOTAGE</p><h2>{t('装得进去，还要跑得起来。','Installed is only the start.')}</h2><p>{t('双开之后，应用能不能正常打开？看看这次录屏里的实际表现，再查看星轨的应用实测记录。','What happens when you open a cloned app? Watch these recorded attempts, then explore Orbit’s app test results.')}</p></div><div class="comparison-grid">'''
    for name,zh,en,resultz,resulte,desc,desce,stamp in clips:
        title=t(zh,en)
        s+=f'''<article class="comparison-card"><div class="comparison-card-heading"><p>{title}</p><h3>{t(resultz,resulte)}</h3></div><video controls muted playsinline preload="none" poster="assets/media/comparison-{name}.jpg" aria-label="{title}"><source src="assets/media/comparison-{name}.mp4" type="video/mp4"></video><div class="comparison-caption"><p>{t(desc,desce)}</p><span>{t('原片','Source')} {stamp} · {t('原速连续节选','Continuous excerpt · 1×')}</span></div></article>'''
    s+=f'''</div><div class="comparison-orbit"><div><p class="eyebrow">ORBIT / TESTED IN PRACTICE</p><h3>{t('星轨的兼容性，逐项看。','Explore Orbit’s compatibility, app by app.')}</h3><p>{t('178 款应用样本，172 款有历史记录。应用版本、设备和结果一并列出；微博与 YouTube 的操作画面，也可以直接播放。','A corpus of 178 apps, with historical records for 172. Versions, devices and outcomes are listed together. Watch Orbit’s recorded Weibo and YouTube workflows on this site.')}</p><a class="button primary" href="{report}#app-catalog">{t('查看应用实测','Explore app results')} ↗</a> <a class="text-link" href="#demos">{t('看阿洛实际操作','Watch Alo in action')} ↓</a></div><div class="comparison-stat"><strong>178</strong><span>{t('应用样本 · 14 个类别','App samples · 14 categories')}</span></div></div><details class="comparison-scope"><summary>{t('这次比较的范围与剪辑说明','Recording scope and edit notes')}</summary><p>{t('素材由用户提供，2026 年 11 月 15 日收录，原片约 81 秒。各片段保持原速与连续顺序，去掉声音并压缩画面；不同片段之间省略了切换和等待。名称按画面显示标注。','User-supplied footage received on November 15, 2026; the source is approximately 81 seconds long. Each excerpt preserves its original speed and sequence, with audio removed and video compressed. App switching and waits between excerpts are omitted. Product names follow the visible interfaces.')}</p><p>{t('原片没有展示完整设备型号、系统版本及竞品版本，因此不作为同机同版本基准测试，也不据此推算兼容率。启动后返回列表是画面观察，具体退出原因未用日志确认。星轨的历史记录单独列出，不代表本片相同应用、相同版本已全部通过。','The source does not show a complete device model, OS version or competitor versions. This is not a matched-device benchmark or a compatibility-rate measurement. Returns to the app list are visible observations; their causes were not confirmed with logs. Orbit’s historical records are listed separately and do not establish passes for the exact apps and versions in these clips.')}</p></details></section>'''
    return s
